#!/usr/bin/env python3\n\"\"\"\nRisk Scoring Test Script\nDemonstrates different scenarios and their risk scores\n\"\"\"\n\nimport sys\nimport os\nsys.path.append(os.path.dirname(os.path.abspath(__file__)))\n\nfrom datetime import datetime\nimport pandas as pd\nimport numpy as np\n\n# Import the scoring functions\nfrom dashboard.components.scorer import extract_features, score_event, load_models\n\ndef test_scoring_scenarios():\n    \"\"\"Test different scoring scenarios\"\"\"\n    print(\"Loading models...\")\n    models, scaler = load_models()\n    \n    if models is None:\n        print(\"❌ Models not found. Please run model training first.\")\n        return\n    \n    print(f\"✅ Models loaded successfully ({len(models)} models)\")\n    print(\"\\n\" + \"=\"*60)\n    print(\"RISK SCORING TEST SCENARIOS\")\n    print(\"=\"*60)\n    \n    # Test scenarios\n    scenarios = [\n        {\n            'name': '🟢 Normal Login',\n            'params': {\n                'timestamp': datetime(2024, 1, 15, 14, 30),  # Business hours\n                'success': True,\n                'device_change': 0,\n                'country_change': 0,\n                'high_risk_country': 0,\n                'rtt': 150,\n                'typical_hour': 14,\n                'user_failure_rate': 0.05\n            }\n        },\n        {\n            'name': '🟡 Suspicious Activity',\n            'params': {\n                'timestamp': datetime(2024, 1, 15, 23, 45),  # Night time\n                'success': True,\n                'device_change': 1,  # New device\n                'country_change': 0,\n                'high_risk_country': 0,\n                'rtt': 300,\n                'typical_hour': 14,\n                'user_failure_rate': 0.1\n            }\n        },\n        {\n            'name': '🔴 High Risk - Classic Takeover',\n            'params': {\n                'timestamp': datetime(2024, 1, 15, 2, 15),  # Night time\n                'success': False,  # Failed login\n                'device_change': 1,  # New device\n                'country_change': 1,  # New country\n                'high_risk_country': 1,  # High risk country\n                'rtt': 800,  # High latency\n                'typical_hour': 14,\n                'user_failure_rate': 0.02,  # Usually successful\n                'time_since_last_login': 0.05  # Very recent\n            }\n        },\n        {\n            'name': '🔴 High Risk - Geographic Anomaly',\n            'params': {\n                'timestamp': datetime(2024, 1, 15, 4, 30),  # Early morning\n                'success': True,\n                'device_change': 0,\n                'country_change': 1,  # New country\n                'high_risk_country': 1,  # High risk country\n                'rtt': 600,\n                'typical_hour': 9,  # Usually logs in at 9 AM\n                'user_failure_rate': 0.01,\n                'user_risk_score': 0.1,  # Usually low risk user\n                'login_consistency': 0.9  # Very consistent user\n            }\n        },\n        {\n            'name': '🔴 High Risk - Rapid Attack',\n            'params': {\n                'timestamp': datetime(2024, 1, 15, 16, 45),\n                'success': True,\n                'device_change': 1,  # New device\n                'country_change': 1,  # New country\n                'high_risk_country': 0,\n                'rtt': 1200,  # Very high latency\n                'typical_hour': 16,\n                'user_failure_rate': 0.05,\n                'time_since_last_login': 0.02,  # 1.2 minutes ago\n                'user_risk_score': 0.2\n            }\n        }\n    ]\n    \n    results = []\n    \n    for scenario in scenarios:\n        print(f\"\\n{scenario['name']}\")\n        print(\"-\" * 40)\n        \n        # Add default values\n        params = {\n            'user_id': 'test_user',\n            'user_login_frequency': 2.0,\n            'login_consistency': 0.7,\n            'user_risk_score': 0.3,\n            'time_since_last_login': 24.0,\n            **scenario['params']\n        }\n        \n        # Extract features and score\n        features = extract_features(params)\n        risk_score, risk_level = score_event(models, scaler, features)\n        \n        results.append({\n            'scenario': scenario['name'],\n            'risk_score': risk_score,\n            'risk_level': risk_level\n        })\n        \n        # Display results\n        print(f\"Risk Score: {risk_score:.3f}\")\n        print(f\"Risk Level: {risk_level}\")\n        \n        # Show key factors\n        factors = []\n        if features['suspicious_combo']:\n            factors.append(\"Device+Country combo\")\n        if features['device_change']:\n            factors.append(\"New device\")\n        if features['country_change']:\n            factors.append(\"New country\")\n        if features['high_risk_country']:\n            factors.append(\"High-risk country\")\n        if features['login_failed']:\n            factors.append(\"Failed login\")\n        if features['is_night']:\n            factors.append(\"Night-time\")\n        if features['rapid_login']:\n            factors.append(\"Rapid login\")\n        if features['hour_deviation'] > 6:\n            factors.append(f\"Time deviation ({features['hour_deviation']:.1f}h)\")\n        if features['rtt_vs_global'] > 300:\n            factors.append(f\"High latency ({params['rtt']}ms)\")\n        \n        if factors:\n            print(f\"Risk Factors: {', '.join(factors)}\")\n        else:\n            print(\"Risk Factors: None detected\")\n    \n    # Summary\n    print(\"\\n\" + \"=\"*60)\n    print(\"SUMMARY\")\n    print(\"=\"*60)\n    \n    for result in results:\n        score_bar = \"█\" * int(result['risk_score'] * 20)\n        print(f\"{result['scenario']:<30} {result['risk_score']:.3f} {score_bar} {result['risk_level']}\")\n    \n    print(\"\\n📊 Score Distribution:\")\n    scores = [r['risk_score'] for r in results]\n    print(f\"   Min: {min(scores):.3f}\")\n    print(f\"   Max: {max(scores):.3f}\")\n    print(f\"   Range: {max(scores) - min(scores):.3f}\")\n    print(f\"   Std Dev: {np.std(scores):.3f}\")\n    \n    print(\"\\n✅ Testing complete!\")\n    print(\"\\nTo see more dynamic behavior, try the Streamlit dashboard with extreme combinations:\")\n    print(\"   - Multiple anomaly indicators simultaneously\")\n    print(\"   - Very high network latency (>1000ms)\")\n    print(\"   - Extreme time deviations (>10 hours)\")\n    print(\"   - High baseline user risk scores (>0.8)\")\n\nif __name__ == \"__main__\":\n    test_scoring_scenarios()\n